select public.prepify_load_bank('Computer Science', 1, $j$[["The \"Pascaline\" (1642) performed basic arithmetic using which specific mechanism?",["Vacuum tubes","Punched cards","Gears and wheels","Transistors"],"C",1,0,"7ca8e8ca9e51",0],["Which component is described as the \"backbone\" of the computer that enables communication between all hardware parts?",["The Central Processing Unit","The Motherboard","The Hard Disk Drive","The Power Supply Unit"],"B",1,0,"6f498f37c8be",0],["Which generation introduced the standard use of keyboards and monitors?",["Second Generation","Third Generation","Fourth Generation","Fifth Generation"],"B",1,0,"4710b27c8d10",0],["\"Self-regulation and stability\" are the defining characteristics of which system type?",["Natural Systems","Artificial Systems","Operating Systems","Network Systems"],"A",1,0,"40cd9ff9194c",0],["Which input device is specifically used to convert \"sound into digital signals\"?",["Scanner","Microphone","Barcode Reader","Digital Camera"],"B",1,0,"2112edea75a6",0],["In the microprocessor, if the system needs to compare two numbers to see which is larger, which unit handles this task?",["Control Unit (CU)","Arithmetic Logic Unit (ALU)","L3 Cache","Memory Address Register"],"B",1,0,"5801bc811ef9",0],["In Von Neumann Architecture, where are \"instructions and program data\" stored according to the core concept?",["In separate physical devices","Together in the same memory","Only in the Accumulator register","Directly on the Control Bus"],"B",1,0,"9572ac25cbc0",0],["What is the specific role of the \"Program Counter (PC)\" register during the instruction cycle?",["It holds the result of a mathematical addition","It contains the memory address of the next instruction to be executed","It decodes the current instruction into binary code","It manages the flow of data to the printer"],"B",1,0,"8819ee05fd3c",0],["If a CPU needs to move data but NOT the memory address, which pathway is utilized?",["Address Bus","Data Bus","Control Bus","Expansion Slot"],"B",1,1,"f6c86dd9b5fd",0],["Within the microprocessor, which unit manages and directs all system activities during instruction execution?",["Arithmetic Logic Unit (ALU)","Control Unit (CU)","Registers","Cache"],"B",1,0,"381d8782c7a0",0],["What distinguishes \"Firmware\" from standard application software?",["It is easily deleted by the user","It is permanently stored on hardware devices","It is used only for word processing","It requires a browser to execute tasks"],"B",1,0,"e2ca64c62219",0],["In data communication, what is the role of the \"Protocol\"?",["To provide the physical path for the message","To act as a set of rules that governs data communications","To convert electrical signals into light","To increase the speed of the sender"],"B",1,0,"cb67e7d3c310",0],["Which communication mode is compared to a \"two-way street\" where traffic flows in both directions at the same time?",["Simplex mode","Half-duplex mode","Full-duplex mode","Asynchronous mode"],"C",1,0,"b414f31fa08c",0],["A network that spans an entire city, covering an area between \"5 to 50 km\", is officially a:",["LAN","WAN","MAN","VPN"],"C",1,0,"756b184c515d",0],["Which category of application software includes tools like \"Microsoft Word\" and \"Google Sheets\"?",["Business Software","Productivity Software","Entertainment Software","Educational Software"],"B",1,0,"b98ca4b4c6f1",0],["\"LMS\" (Learning Management Systems) are categorized as which type of software?",["Productivity","Business","Educational Software","System Utility"],"C",1,0,"1d43f53920a4",0],["\"Mnemonics\" like MOV and ADD are the symbolic codes used in which language?",["Machine Language","Assembly Language","High Level Language","Java"],"B",1,0,"4abcc84f95f4",0],["In a \"Star Topology\", what is the consequence if the central hub or switch fails?",["Only one computer stops working","The whole network goes down","Data starts traveling in a circle","The network automatically switches to Bus topology"],"B",1,0,"fe67ce7675b4",0],["Which Internet technology allows data packets to potentially take \"different routes\" to reach their destination?",["Circuit Switching","Packet Switching","Simplex Transmission","Synchronous Timing"],"B",1,0,"7df53f62be55",0],["What is listed as a significant \"Disadvantage\" of the Internet regarding human social behavior?",["Global Connectivity","Digital Addiction and social isolation","Real-time communication","Enhanced productivity"],"B",1,0,"628414348060",0],["\"Walkie-talkies\" are the classic example of which communication mode?",["Simplex","Half-duplex","Full-duplex","Synchronous"],"B",1,0,"561289d8be77",0],["Which transmission type uses \"Start and Stop bits\" because character timing is variable?",["Synchronous","Asynchronous","Parallel","Full-duplex"],"B",1,0,"11bf6e14cc0f",0],["When you are \"reading a web page\" on your browser, which protocol is working behind the scenes?",["FTP","HTTP","SMTP","TCP"],"B",1,0,"ce3fcabcfa9e",0],["FORTRAN and ALGOL are classic examples of which high-level language category?",["Procedural Languages","Structured Languages","Object-Oriented Languages","Machine Languages"],"A",1,0,"bf3521b9dd76",0],["Data transmission from a computer to a printer, or broadcasting via radio and television, takes place in which mode?",["Simplex mode","Half-duplex mode","Full-duplex mode","Asynchronous mode"],"A",1,0,"9a06fde71277",0],["Without which of the following component can two devices be physically connected but still unable to communicate or exchange information?",["Receiver","Medium","Protocol","Notice board"],"C",1,0,"3bedfe7f41f7",0],["Which layer of the OSI model is explicitly responsible for converting data into a format that ensures compatibility across different systems?",["Application Layer","Presentation Layer","Session Layer","Transport Layer"],"B",1,0,"bde94699efca",0],["Which OSI layer determines the optimal path for data transmission using devices like routers?",["Physical Layer","Data Link Layer","Network Layer","Application Layer"],"C",1,0,"7dbd018ad470",0],["The modern global Internet originally evolved from a 1960s research project designed for military installations and research institutions. What was the name of this project?",["World Wide Web","Internet of Things","ARPANET","ISP Web"],"C",1,0,"4e5c563ff66c",0],["A network setup that is typically smaller and usually consists of \"between two and ten computers\" is called:",["Client/Server Network","Peer-to-Peer Network","Dedicated Server Network","Central Switch Network"],"B",1,0,"267656649b92",0],["Identify the system that exists independently of human design and invention.",["Solar system","Traffic system","School management system","Keyboard"],"A",1,0,"5b57fd7083b8",0],["During the execute stage of the fetch-decode-execute cycle, which component actively transforms data using logic gates, while the others fetch, decode or hold data?",["Control Unit (CU)","Memory Unit (MU)","Arithmetic Logic Unit (ALU)","Register unit"],"C",3,0,"3a277ae8ac67",0],["Which memory component temporarily stores active programs and data during execution but loses its contents when the power is turned off?",["Hard disk","ROM","RAM","USB flash drive"],"C",1,0,"d81e6fc4dc46",0],["Whose invention provided the conceptual foundation for modern programmable computers?",["Alan Turing","Charles Babbage","Bill Gates","John von Neumann"],"B",3,0,"ac13c9469294",0],["If a computer starts successfully but no application software can run, which of the following software is most likely still functioning?",["MS Word","Adobe Photoshop","Windows 11","Google Chrome"],"C",5,1,"e45a36380f41",0],["A computer executes instructions accurately because one CPU component directs the activities of all other components. Which function does this component perform?",["Perform calculations","Store data permanently","Manage and coordinate all computer operations","Display graphics"],"C",3,1,"ccf771860ed4",0],["Which type of memory is located closest to the CPU and stores frequently accessed data for faster processing?",["RAM","Cache memory","Hard disk","ROM"],"B",3,0,"41a65780573c",0],["A system developed to solve a particular human need is classified as an artificial system because it:",["occurs naturally in the environment","is created by humans to achieve a specific goal","cannot be broken down into smaller parts","does not require any input"],"B",3,0,"560fce034e8a",0],["Which of the following storage devices generally has the largest storage capacity in a typical modern PC?",["SSD (solid state drive)","CD-ROM","RAM","Cache memory"],"A",3,0,"5bc947eb3b87",0],["A computer stores both program instructions and data in the same memory before execution. This feature is based on which concept?",["Stored-program concept","Graphical user interface","Mechanical computing","Cloud computing"],"A",3,1,"144c0e643b15",0],["A user wants to organize numerical data, perform calculations and create charts. Which software is most suitable?",["Linux","macOS","MS Excel","BIOS"],"C",1,1,"32b367e8532a",0],["If a computer stores information in the smallest possible binary form, which unit is being used?",["Byte","Kilobyte","Bit","Nibble"],"C",1,0,"8930c261be03",0],["A team is assigned to develop an operating system instead of assembling computer hardware. Which area of work does this task belong to?",["Manufacturing processors","Designing circuits","Developing programs and operating systems","Building monitors"],"C",3,1,"42a7c9227eb6",0],["A teacher wants to convert a printed worksheet into an editable digital document. Which device should be used?",["Monitor","Printer","Speaker","Scanner"],"D",1,1,"f1ee72d031d4",0],["A computer loses the contents of its working memory when power is turned off, while another storage device keeps its data. This difference is mainly due to:",["Volatility of the memory","Colour and shape","Price and brand","The size of the device"],"A",3,1,"3d8f46bd4b6d",0],["Which set of symbols is sufficient to represent all data and instructions in a digital computer?",["0 to 9","0 and 1","1 and 2","0 to 7"],"B",1,0,"5182d47e9b3a",0],["A network gives each computer its own separate connection to a central device. Which is a direct advantage of this arrangement?",["Failure of one workstation does not affect the others","It needs no connecting device","It uses only a single communication cable","Every computer is directly connected to every other computer"],"A",5,1,"52c03f7eecf8",0],["Which component interprets and executes program instructions while coordinating all processing in a computer?",["RAM","Motherboard","CPU","Hard disk"],"C",1,0,"80bf1e7151f5",0],["A student scans old photos, types a report in MS Word and then prints it. How are the scanner, MS Word and the printer classified by function?",["Output, system software, input","Input, application software, output","Storage, utility software, input","Processing, hardware, software"],"B",5,1,"5a81bad03cc3",0],["A pyramid shows CPU registers at the top (smallest, fastest, costliest), then cache, then RAM, and the hard disk at the bottom (largest, slowest, cheapest). This arrangement illustrates the:",["Memory hierarchy","Processing cycle","Network topology","Boot sequence"],"A",3,1,"0020d33c7880",0],["A gamer's high-graphics game runs very slowly. He wants the CPU to reach game data much faster than reading it from the hard drive. Which component should he upgrade?",["Hard drive capacity","Monitor size","RAM size","Keyboard speed"],"C",5,1,"049052ab3694",0],["A program calculates student grades. The Control Unit directs the flow and the result goes to the monitor. Which part actually calculates the average marks?",["Control Unit","Monitor","Arithmetic Logic Unit (ALU)","Hard disk"],"C",3,1,"f6aec489c11c",0],["Fatima saves her data on a USB drive, unplugs it overnight, and finds all her data still there the next day. This shows the USB drive is a:",["Volatile storage device","Non-volatile storage device","Primary storage device","Temporary storage device"],"B",3,1,"74c87272560b",0],["A teacher shows three pictures: a student typing on a keyboard, the CPU showing \"Processing\", and a printer producing a report. What do the three steps represent?",["Output, processing, input","Input, processing, output","Storage, input, output","Processing, storage, output"],"B",1,1,"2913251924f0",0],["A new laptop (16 GB RAM, 512 GB SSD) costs five times more than an old one (4 GB RAM, 256 GB HDD). The price difference is MOSTLY due to the new laptop having:",["A larger screen","More RAM and a faster SSD","A different coloured case","More USB ports"],"B",3,1,"cdb5833a8a61",0],["A hospital system takes heartbeat data, compares it with normal levels and alerts a nurse if the heart stops. This describes the basic functions of a computer system as:",["Artificial system","Data, information and processing","Natural system","Networking only"],"B",5,1,"83480b28e45d",0],["During data communication, information travels through a fibre-optic cable from one device to another. The fibre-optic cable is the:",["Sender","Receiver","Transmission medium","Protocol"],"C",3,1,"d28f7ef219e6",0],["A school has computer labs in two cities, each with its own local network, and the two networks are joined so teachers can share one database. The connection between the two is best described as a:",["PAN","LAN","WAN","VPN"],"C",5,1,"b7c40bd3e0fb",0],["Student A says, \"Hardware is useless without software.\" Student B says, \"Software cannot run without hardware.\" Which conclusion is correct?",["Hardware is more important than software","Hardware and software are interdependent","Software is more important than hardware","They are independent of each other"],"B",3,1,"11e5648cbd9c",0],["A student uses Wi-Fi to open a learning portal hosted in another country; the data passes through several interconnected networks. Which technology mainly enables this?",["LAN","Internet","Star topology","Ring topology"],"B",3,1,"e0dfc8967df2",0],["A student records a voice note for an assignment. Which input device turns the student's voice into digital signals?",["Scanner","Microphone","Speaker","Webcam"],"B",1,1,"2112edea75a6",0],["A cable company links its offices spread across one city, about 30 km apart. This network is a:",["LAN","MAN","WAN","PAN"],"B",3,1,"756b184c515d",0],["Which register holds the address of the instruction to be fetched next?",["Accumulator","Program Counter","Instruction Register","Memory Data Register"],"B",3,0,"8819ee05fd3c",0],["Short symbolic codes such as MOV, ADD and SUB are used in:",["machine language","assembly language","high-level languages only","HTML"],"B",1,0,"4abcc84f95f4",0],["During a phone call both people can talk and listen at the same time. This uses which transmission mode?",["Simplex","Half-duplex","Full-duplex","Broadcast"],"C",3,1,"b414f31fa08c",0],["Data that flows in only one direction, as from a keyboard to a computer, uses which mode?",["Simplex","Half-duplex","Full-duplex","Multiplex"],"A",3,0,"9a06fde71277",0],["The part of the CPU that directs the flow of data and tells the other components what to do is the:",["ALU","Control Unit","Cache","Hard disk"],"B",3,0,"381d8782c7a0",0],["Which protocol does a web browser use to request and load web pages?",["SMTP","FTP","HTTP","POP3"],"C",3,0,"ce3fcabcfa9e",0],["The key idea of the Von Neumann architecture is that:",["instructions and data are stored together in the same memory","instructions are stored only on paper","data is kept only in registers","each program needs its own CPU"],"A",3,0,"9572ac25cbc0",0],["The Internet grew out of a 1960s U.S. research network called:",["ARPANET","Ethernet","World Wide Web","Bluetooth"],"A",1,0,"4e5c563ff66c",0],["A shopkeeper wants to turn a printed price list into a digital image on the computer. Which device should be used?",["Printer","Scanner","Plotter","Projector"],"B",1,1,"f1ee72d031d4",0],["Which component is called the \"brain\" of the computer because it processes all instructions?",["RAM","Hard disk","CPU","Monitor"],"C",1,0,"80bf1e7151f5",0],["A walkie-talkie lets only one person speak at a time, although both can speak. This is:",["simplex mode","half-duplex mode","full-duplex mode","broadcast mode"],"B",3,1,"b414f31fa08c",0]]$j$::jsonb, true);
select public.prepify_load_bank('Computer Science', 2, $j$[["\"How to stop infectious diseases?\" is a real-world problem belonging to which field?",["Economic","Education","Healthcare","Transportation"],"C",3,0,"31cbc2c1a8cc",0],["In computer science, a \"computing problem\" is specifically defined as a problem that is solved:",["Only by using the internet.","Step-by-step using computation.","By a human without a machine.","Instantly without any steps."],"B",3,0,"ed21a0d2fd91",0],["When checking if a specific number is \"Prime\" or \"Not Prime,\" you are dealing with which type of computing problem?",["Search Problem","Decision Problem","Counting Problem","Abstraction Problem"],"B",3,0,"6a8893c1178b",0],["In a \"Search Problem,\" which element represents the specific moves that transition from one node to another?",["Initial State","Operations","Goal","Decision Diamond"],"B",3,0,"23457bed8c15",0],["To solve a search problem, the \"target of end condition\" is officially known as the:",["Initial State","Operation","Goal","Start State"],"C",3,0,"042ebeb44932",0],["If you have 5 shirts and 3 pants, how many \"total possible casual dresses\" can you form?",["8","15","53","2"],"B",3,0,"e7d4b6ab730b",0],["If you enter your home and see water on the floor, what do you need to solve such problems?",["High-speed internet access","Reasoning skills that are based on evidence and facts","A calculator to measure the volume of water","Advanced programming knowledge"],"B",3,0,"295bf22eb22f",0],["In the I-P-O model, which term refers specifically to the \"requirements from the environment\"?",["Input","Process","Output","Storage"],"A",3,0,"b2d4e93689d9",0],["For a programmer, an I-P-O chart is considered to be a:",["Type of hardware.","Handy tool to solve problems.","Decision problem.","Form of machine code."],"B",3,1,"7291e215585f",0],["In an I-P-O chart, the \"Process\" column is defined as:",["Data entered into the system.","Operations that will be applied on the input.","Data that has been turned into information.","The hardware used for the computation."],"B",3,0,"5ad5b0b69e91",0],["If you are calculating the \"Average of 5 numbers,\" the division operation would be listed in which section of the I-P-O chart?",["Input","Process","Output","Storage"],"B",3,0,"ac3f7b91be03",0],["What is the official definition of \"Output\" in the I-P-O tabular form?",["Requirements from the environment.","Operations applied to the data.","Data that has been turned into the Information.","The physical screen of the computer."],"C",3,0,"38c432467c03",0],["\"Computational Thinking\" is often described as an extension of which type of thinking?",["Mathematical Thinking","Logical Thinking","Creative Thinking","Fast Thinking"],"B",3,0,"90b423e58637",0],["Which property of computational thinking involves \"removing the unnecessary details\" to focus on essential info?",["Decomposition","Abstraction","Pattern Recognition","Algorithm Design"],"B",3,0,"5cffaee82f48",0],["The process of \"examining a problem for similarities between previously solved problems\" is:",["Decomposition","Abstraction","Pattern Recognition","Algorithm Design"],"C",3,0,"f5d1de47cf3e",0],["\"Actual designing of solution\" and \"creating step-by-step plan\" defines:",["Logical Thinking","Algorithm Design","I-P-O Modeling","Problem Analysis"],"B",3,0,"843da82e75a9",0],["In the \"Video Game\" example, ignoring the \"weather\" while focusing on the \"exit\" is an example of:",["Decomposition","Abstraction","Logical Thinking","Input Identification"],"B",3,0,"9e12853f10bf",0],["Treating \"Six enemies as a single enemy\" because they behave the same way is an example of:",["Decomposition","Abstraction","Pattern Recognition","Search Problem"],"C",3,0,"98cbca9cb604",0],["What is the benefit of developing \"algorithmic thinking skills\"?",["You become a hardware engineer.","You become a better problem solver.","You can type 100 words per minute.","You no longer need a computer."],"B",3,0,"3c766d8e8a64",0],["Which solution design method is described as a \"diagrammatic representation of an algorithm\"?",["Flowchart","Concept Map","I-P-O Model","Machine Code"],"A",3,0,"48f2b7f4cb63",0],["Every flowchart should officially start with a \"trigger,\" which is represented by which shape?",["Rectangle","Parallelogram","Oval shape","Diamond"],"C",3,0,"762f72af8eca",0],["Which graphical shape represents the \"Input to the flowchart\"?",["Oval","Parallelogram","Rectangle","Diamond"],"B",3,0,"68315839bd0e",0],["When a formula (like Area = (Base x Height) / 2) is applied in a flowchart, which symbol is used?",["Oval","Parallelogram","Rectangle","Diamond"],"C",3,0,"d6b58b88e32c",0],["When a flowchart needs to check a condition (like \"Is Grade > 50?\"), which symbol is used?",["Rectangle","Diamond","Oval","Circle"],"B",3,0,"b597eab241a7",0],["Why might a flowchart have \"multiple ends\"?",["Because the programmer got confused.","Because of the possibility of multiple decision points.","Because it is a complex search problem.","Because the trigger was not an oval."],"B",3,0,"aedd090c0c79",0],["Which software tool is mentioned as famous for drawing various types of diagrams, including flowcharts?",["LARP","Microsoft Visio","Canva","ChatGPT"],"B",3,0,"7a09d8f15270",0],["The LARP programming language is unique because it uses:",["Only binary code (0s and 1s).","Semi-natural syntax.","Only graphical icons.","Complex machine language."],"B",3,0,"18ff41194b30",0],["In the \"Video Game Development\" concept map, what are the three sub-concepts under \"Game Design\"?",["Gameplay Mechanics, Level Design, and Storyline.","Coding, Scripting, and Engines.","2D Art, 3D Models, and Animation.","Sound Effects, Music, and Voice Acting."],"A",3,0,"a09ed3022b67",0],["Which of the following methods are mentioned for designing a solution?",["Flowcharts and Source Code","Concept Maps and Pseudo-code","Flowcharts and Concept Maps","Algorithms and Charts"],"C",3,0,"3205754681b7",0],["A developer divides a complex payroll system into employee records, salary calculation and report generation before implementation. Which computational thinking skill is being applied?",["Pattern recognition","Decomposition","Debugging","Selection"],"B",3,1,"5d026e3c8f31",0],["An algorithm repeats the same instructions forever without ever reaching its final step. Which characteristic of a good algorithm has been violated?",["Effectiveness","Finiteness","Clarity","Input"],"B",5,1,"bee02fe0f9cf",0],["Which situation is best classified as a computational problem rather than an ordinary daily-life problem?",["Choosing a dress for a party","Calculating the shortest route between two cities using a computer","Watering plants in a garden","Cleaning a classroom"],"B",3,0,"89cd78400497",0],["An algorithm calculates the average age of four students. Which condition must the input satisfy for the result to be meaningful?",["Ages must be whole numbers","The input ages must be positive","The sum must be divisible by 4","The data must be sorted"],"B",5,1,"72d79652573d",0],["A program checks whether water has reached 100 °C before displaying \"Boiling\". Which computational thinking skill is mainly used?",["Logical reasoning","Random guessing","Pattern recognition","Sequencing"],"A",3,1,"57209756d201",0],["A teacher wants the total number of students who scored above 80 in a class. This problem is best classified as a:",["Decision problem","Search problem","Counting problem","Sorting problem"],"C",3,1,"6f2fc0bbc0fb",0],["A program must check whether a student's marks are 50 or more before displaying \"Pass\". Which flowchart symbol represents this condition?",["Parallelogram","Rectangle","Diamond","Oval"],"C",1,1,"41f0b043f2ac",0],["Which problem needs a \"Yes\" or \"No\" answer rather than locating or counting an item?",["Find a student's roll number","Count the absent students","Decide whether a student has paid the fee","Arrange students alphabetically"],"C",3,0,"c16a4354af9a",0],["Which computational thinking skill is most directly responsible for spotting a solution that can be reused for similar problems?",["Algorithmic thinking","Pattern recognition","Abstraction","Decomposition"],"B",3,0,"8f79bd880873",0],["In which situation is abstraction more appropriate than decomposition?",["Dividing a payroll system into modules","Ignoring students' favourite colours while designing a student database","Preparing steps to calculate percentages","Searching for a student's record"],"B",5,0,"26f422f7afa0",0],["Which representation focuses on the sequence of operations rather than the relationships among ideas?",["Concept map","Flowchart","Mind map","Table"],"B",3,0,"c4ffcdd6a1cd",0],["In which situation is logical thinking applied before algorithmic thinking?",["Deciding whether a voter is eligible based on age","Drawing flowchart symbols","Saving a program file","Installing software"],"A",5,0,"04033076674c",0],["Which computational thinking property reduces a problem's complexity without dividing it into smaller parts?",["Pattern recognition","Abstraction","Decomposition","Sequencing"],"B",5,0,"317cfe29470c",0],["Which task is least likely to be classified as a search problem?",["Locating a student's admission record","Finding a word in a dictionary","Deciding whether a password is valid","Searching for a contact number"],"C",5,0,"8d86418ab5a0",0],["A programmer completes every processing step correctly but forgets to display the result. Which essential property of an algorithm is missing?",["Input","Output","Clarity","Finiteness"],"B",3,1,"7ad02b928a02",0],["To calculate a student's total marks you split the program into: input the marks, calculate the sum, display the result. This splitting is known as:",["Pattern recognition","Decomposition","Abstraction","Debugging"],"B",3,1,"6ae9cdd61e0b",0],["Which problem is most likely to need decomposition before an effective solution can be developed?",["Adding two numbers","Finding today's date","Developing a school management system","Switching on a computer"],"C",3,0,"908d6c612c43",0],["A student first studies a problem carefully before applying any solution. According to the LARP approach, this stage is:",["Learning","Applying","Reflecting","Practising"],"A",3,1,"e2288aac8bed",0],["A school's fee system is split into fee collection, fee calculation and report generation. Which computational thinking skill is being used?",["Abstraction","Decomposition","Pattern recognition","Sequencing"],"B",1,1,"bd8f75719ca5",0],["Ali notices that every monthly electricity bill is calculated using the same formula. This observation demonstrates:",["Pattern recognition","Abstraction","Flowcharting","Sequencing"],"A",3,1,"8351434bf95b",0],["While designing a student database, Sana ignores students' favourite colours because they are irrelevant. This is an example of:",["Decomposition","Abstraction","Sequencing","Testing"],"B",1,1,"bbed1ebe96cf",0],["What is the output of this algorithm? Start; X = 1; print X; X = X + 2; if X < 6 go back to \"print X\"; End.",["1, 2, 3, 4, 5","1, 3, 5","1, 3, 5, 7","2, 4, 6"],"B",5,0,"a7d32910d628",0],["A bank ATM follows a fixed sequence of instructions whenever cash is withdrawn. This sequence is known as:",["Data storage","An algorithm","An input device","A database"],"B",1,1,"27991b6481a6",0],["A teacher asks students to identify common characteristics among birds, insects and mammals. Which computational thinking skill is being applied?",["Pattern recognition","Abstraction","Sequencing","Coding"],"A",3,1,"1cbfa1cd7bb5",0],["In a flowchart for total marks, a student uses a diamond to check whether marks are greater than 50. The diamond represents a:",["Start/End","Process","Input/Output","Decision"],"D",1,1,"8583b48ca7ed",0],["Students must show how \"Computer\", \"Hardware\", \"Software\" and \"Data\" are related, not the order of steps. Which tool should be used?",["Algorithm","Flowchart","Concept map","IPO chart"],"C",3,1,"4c5a6f23d96f",0],["A company's online exam system has registration, paper generation, attendance and result modules, so the team divides it into smaller tasks first. This is mainly because the project is a:",["Simple problem","Logical problem","Counting problem","Complex problem"],"D",3,1,"26af2eaf700f",0],["A weather department analyses millions of temperature readings every day to predict rainfall. Which type of problem is mainly being solved?",["Simple problem","Computational problem","Daily-life problem","Decision problem"],"B",3,1,"a42220043ecd",0],["A programmer ignores unnecessary design details while developing a library management system. Which computational thinking concept is applied?",["Pattern recognition","Sequencing","Abstraction","Debugging"],"C",3,1,"6836dce5c9e8",0],["Before coding, Ahmed draws a flowchart showing all the steps and decisions. The main purpose of the flowchart is to:",["Increase complexity","Graphically represent the algorithm","Store data permanently","Replace the program code"],"B",3,1,"fe726ca40a4b",0],["Planning a school sports day is split into smaller tasks: booking the ground, making teams and arranging prizes. This skill is called:",["Abstraction","Decomposition","Pattern recognition","Debugging"],"B",3,1,"bd8f75719ca5",0],["An algorithm must produce at least one result. This property is called:",["input","output","finiteness","definiteness"],"B",3,0,"7ad02b928a02",0],["A librarian wants to know how many books were borrowed this week. This is best classified as a:",["sorting problem","counting problem","searching problem","decision problem"],"B",3,1,"6f2fc0bbc0fb",0],["In a flowchart, the step \"Total = Price × Quantity\" is drawn inside a:",["diamond","rectangle","oval","parallelogram"],"B",3,0,"d6b58b88e32c",0],["Which flowchart symbol is used for a question with a Yes/No answer, such as \"Is Age ≥ 18?\"",["Oval","Rectangle","Diamond","Parallelogram"],"C",1,0,"b597eab241a7",0],["A city map shows the roads but leaves out trees and buildings. Which computational thinking skill does this show?",["Decomposition","Abstraction","Pattern recognition","Algorithm design"],"B",3,1,"5cffaee82f48",0],["A student notices that the method for finding the average of test marks also works for average temperatures. This is:",["abstraction","pattern recognition","decomposition","debugging"],"B",3,1,"8f79bd880873",0],["A diagram that shows the steps of an algorithm using standard symbols joined by arrows is a:",["concept map","flowchart","pseudocode","source code"],"B",1,0,"48f2b7f4cb63",0],["In a search problem, the state we want to reach is called the:",["initial state","goal","operation","path"],"B",3,0,"042ebeb44932",0],["In an I-P-O chart, the marks a student types into a result program are the:",["input","process","output","storage"],"A",3,1,"b2d4e93689d9",0],["Which flowchart symbol marks the Start and End of an algorithm?",["Rectangle","Diamond","Oval (terminal)","Parallelogram"],"C",1,0,"48f2b7f4cb63",0]]$j$::jsonb, true);
